<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            return current.length > 0 ? String(current[0]) : defaultValue;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, rawValue, min, max) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);

        if (!valueMainDisplay) return;

        let numericValue = min;
        if(rawValue !== "N/A" && !isNaN(parseFloat(rawValue))) {
            numericValue = parseFloat(rawValue);
        }
        valueMainDisplay.innerText = String(rawValue);

        if (progressBar) {
            const finalValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (finalValue >= max ? 100 : 0) : ((finalValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isCollapsed = content.classList.toggle('collapsed');
        arrow.innerText = isCollapsed ? '▶' : '▼';
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('card-title').innerText = "无法加载状态数据";
                return;
            }
            const gameData = messages[0].data;
            const characterData = gameData.display_data || gameData.stat_data;
            if (!characterData) {
                 document.getElementById('card-title').innerText = "状态数据丢失";
                 return;
            }

            const characterKey = "姜柚";
            const userKey = "user";

            document.getElementById('date-value').innerText = SafeGetValue(characterData, '日期');
            document.getElementById('time-value').innerText = SafeGetValue(characterData, '时间');

            if(characterData.hasOwnProperty(userKey)){
                document.getElementById('user-location').innerText = SafeGetValue(characterData[userKey], '当前位置');
            }
            if (characterData.hasOwnProperty(characterKey)) {
                document.getElementById('jiangyou-location').innerText = SafeGetValue(characterData[characterKey], '当前位置');

                updateProgressBar('jiangyou-lovebud-bar', 'jiangyou-lovebud', SafeGetValue(characterData[characterKey], '恋情萌芽度', '0'), 0, 100);
                updateProgressBar('jiangyou-fade-bar', 'jiangyou-fade', SafeGetValue(characterData[characterKey], '男友幻灭度', '0'), 0, 100);

            } else {
                 document.getElementById('jiangyou-location').innerText = '数据缺失';
                 updateProgressBar('jiangyou-lovebud-bar', 'jiangyou-lovebud', '0', 0, 100);
                 updateProgressBar('jiangyou-fade-bar', 'jiangyou-fade', '0', 0, 100);
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
